parameters.jsCode:
// Nombre de pages de 50 notifications RASFF à lire, les plus récentes d'abord. 4 pages ≈ 2 semaines de RASFF.
// Premier lancement : mettre 120 pour récupérer environ un an d'historique, puis revenir à 4.
const PAGES = 4;
return Array.from({ length: PAGES }, (_, i) => ({ json: { page: i + 1 } }));

// Transforme les réponses du RASFF en lignes pour ie.alertes_conformite.
// Garde uniquement les produits originaires d'Afrique de l'Ouest et repère la mangue, le piment et l'ananas.
// L'interface du RASFF n'est pas documentée : les champs sont cherchés sous plusieurs noms possibles
// et la notification d'origine est conservée dans « brut ».
const PAYS = {
  CI: "Côte d'Ivoire", SN: 'Sénégal', ML: 'Mali', BF: 'Burkina Faso', BJ: 'Bénin', GH: 'Ghana', GN: 'Guinée',
  TG: 'Togo', NG: 'Nigeria', NE: 'Niger', GM: 'Gambie', GW: 'Guinée-Bissau', SL: 'Sierra Leone', LR: 'Liberia',
  CV: 'Cap-Vert', MR: 'Mauritanie',
};
const NOMS = {
  'ivory coast': 'CI', "cote d'ivoire": 'CI', senegal: 'SN', mali: 'ML', 'burkina faso': 'BF', benin: 'BJ',
  ghana: 'GH', guinea: 'GN', togo: 'TG', nigeria: 'NG', niger: 'NE', gambia: 'GM', 'the gambia': 'GM',
  'guinea-bissau': 'GW', 'guinea bissau': 'GW', 'sierra leone': 'SL', liberia: 'LR', 'cape verde': 'CV',
  'cabo verde': 'CV', mauritania: 'MR',
};
const norm = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’`]/g, "'").trim().toLowerCase();

// Toutes les valeurs texte d'un champ, qu'il soit texte, liste ou objet ({ isoCode, name, description… }).
const textes = (v, prof = 0) => {
  if (v === null || v === undefined || prof > 3) return [];
  if (typeof v === 'string' || typeof v === 'number') return String(v).trim() ? [String(v).trim()] : [];
  if (Array.isArray(v)) return v.flatMap((x) => textes(x, prof + 1));
  if (typeof v === 'object') {
    const t = ['isoCode', 'iso', 'code', 'name', 'description', 'label', 'value']
      .filter((k) => v[k] !== undefined)
      .flatMap((k) => textes(v[k], prof + 1));
    return t.length ? t : Object.values(v).flatMap((x) => textes(x, prof + 1));
  }
  return [];
};
const premier = (x, ...cles) => {
  for (const k of cles) {
    const t = textes(x[k])[0];
    if (t) return t;
  }
  return '';
};

const origines = (x) => {
  const codes = new Set();
  const valeurs = Object.entries(x).filter(([k]) => /origin/i.test(k)).flatMap(([, v]) => textes(v));
  for (const v of valeurs) {
    if (/^[A-Z]{2}$/.test(v) && PAYS[v]) codes.add(v);
    for (const morceau of v.split(/[,;]/)) if (NOMS[norm(morceau)]) codes.add(NOMS[norm(morceau)]);
  }
  // Repli : le titre du RASFF suit presque toujours le modèle « danger in produit from pays (via pays) ».
  if (!codes.size) {
    const apres = norm(premier(x, 'subject', 'title')).split(/\bfrom\b/)[1]?.split(/\bvia\b/)[0] ?? '';
    for (const morceau of apres.split(/,| and |\(|\)/)) if (NOMS[norm(morceau)]) codes.add(NOMS[norm(morceau)]);
  }
  return [...codes];
};

// Accepte 2026-07-10, 10-07-2026 11:38:37 (format du RASFF) et un horodatage en secondes ou millisecondes.
const dateIso = (v) => {
  const s = String(v ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{2})[-/.](\d{2})[-/.](\d{4})/);
  if (m) return `${m[3]}-${m[2]}-${m[1]}`;
  if (/^\d{10,13}$/.test(s)) return new Date(Number(s) * (s.length === 10 ? 1000 : 1)).toISOString().slice(0, 10);
  return null;
};

const produit = (t) => (/mango/.test(t) ? 'mangue' : /chil+i|capsicum/.test(t) ? 'piment' : /pineapple/.test(t) ? 'ananas' : 'autre');
const danger = (t) =>
  /aflatoxin|ochratoxin|mycotoxin|fumonisin/.test(t) ? 'mycotoxines'
  : /pesticide|residue|chlorpyrifos|dimethoate|omethoate|carbendazim|imidacloprid|cypermethrin|acetamiprid|thiamethoxam|ethylene oxide/.test(t) ? 'pesticides'
  : /salmonella|listeria|escherichia|e\. ?coli|norovirus|hepatitis|bacillus|mould|enterobacter|vibrio/.test(t) ? 'microbiologie'
  : /sudan|colour|color|sulphite|sulfite|additive|benzoic|sorbic/.test(t) ? 'additifs'
  : /insect|fruit fl|bactrocera|ceratitis|thaumatotibia|harmful organism|larva|infest|weevil/.test(t) ? 'organismes nuisibles'
  : /certificate|document|unauthori[sz]ed|illegal|labell/.test(t) ? 'documentaire'
  : 'autre';

const estNotif = (o) => o && typeof o === 'object' && !Array.isArray(o) && ('subject' in o || 'notifId' in o || 'reference' in o);
const trouverListe = (o, prof = 0) => {
  if (Array.isArray(o)) return o;
  if (!o || typeof o !== 'object' || prof > 3) return [];
  for (const k of ['notifications', 'content', 'items', 'results', 'data', 'list', 'records']) if (Array.isArray(o[k])) return o[k];
  for (const v of Object.values(o)) {
    const l = trouverListe(v, prof + 1);
    if (l.length && typeof l[0] === 'object') return l;
  }
  return [];
};

const reponses = $input.all().map((i) => i.json);
const notifs = reponses.flatMap((r) => (estNotif(r) ? [r] : trouverListe(r)));
const vues = new Set();
const dates = [];
const lignes = [];
for (const x of notifs) {
  const reference = premier(x, 'reference', 'notificationReference', 'notifId', 'id');
  if (!reference || vues.has(reference)) continue;
  vues.add(reference);
  const d = dateIso(premier(x, 'ecValidationDate', 'notificationDate', 'validationDate', 'date', 'createdDate'));
  if (d) dates.push(d);
  const codes = origines(x);
  if (!codes.length) continue;
  const titre = premier(x, 'subject', 'title') || `Notification RASFF ${reference}`;
  const categorie = premier(x, 'productCategory', 'productType');
  const t = norm(`${titre} ${categorie} ${premier(x, 'hazards', 'hazard', 'hazardCategory')}`);
  const id = textes(x.notifId ?? x.notificationId ?? x.id)[0] ?? '';
  lignes.push({
    source: 'rasff',
    reference,
    date_alerte: d ?? new Date().toISOString().slice(0, 10),
    produit: produit(t),
    pays: codes[0],
    pays_nom: codes.map((c) => PAYS[c]).join(', '),
    danger: danger(t),
    gravite: premier(x, 'riskDecision', 'risk', 'riskLevel'),
    decision: premier(x, 'notificationClassification', 'classification', 'notificationType'),
    titre,
    detail: categorie,
    url: /^\d+$/.test(id) ? `https://webgate.ec.europa.eu/rasff-window/screen/notification/${id}` : null,
    brut: x,
  });
}
dates.sort();
const echecs = reponses.filter((r) => r.error).map((r) => JSON.stringify(r.error).slice(0, 200));
let erreur = echecs.length ? `RASFF : ${echecs.length} page(s) en erreur. ${echecs[0]}` : '';
if (!notifs.length) erreur ||= `RASFF : aucune notification lue. Réponse : ${JSON.stringify(reponses[0] ?? {}).slice(0, 300)}`;
return [{ json: {
  lignes,
  recues: vues.size,
  afrique_ouest: lignes.length,
  periode_lue: dates.length ? `${dates[0]} → ${dates.at(-1)}` : null,
  erreur,
} }];

// Lit l'onglet « alertes » du Google Sheet : interceptions EUROPHYT/TRACES, rapports AGRINFO, infos terrain…
// Colonnes : date, source, produit, pays, danger, decision, titre, detail, lien.
// Chaque ligne reçoit une empreinte : modifier une ligne met à jour la même alerte au lieu d'en créer une autre.
const PAYS = {
  CI: "Côte d'Ivoire", SN: 'Sénégal', ML: 'Mali', BF: 'Burkina Faso', BJ: 'Bénin', GH: 'Ghana', GN: 'Guinée',
  TG: 'Togo', NG: 'Nigeria', NE: 'Niger', GM: 'Gambie', GW: 'Guinée-Bissau', SL: 'Sierra Leone', LR: 'Liberia',
  CV: 'Cap-Vert', MR: 'Mauritanie',
};
const texte = (v) => String(v ?? '').trim();
const norm = (s) => texte(s).normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[’`]/g, "'").toLowerCase();
const NOMS = Object.fromEntries(Object.entries(PAYS).map(([c, n]) => [norm(n), c]));
Object.assign(NOMS, { 'ivory coast': 'CI', 'cote divoire': 'CI', senegal: 'SN', benin: 'BJ', guinea: 'GN', gambia: 'GM' });
// Accepte 2026-10-09, 09/10/2026 et le numéro de série de Google Sheets.
const date = (v) => {
  const s = texte(v);
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  if (/^\d{5}(\.\d+)?$/.test(s)) return new Date(Date.UTC(1899, 11, 30) + Number(s) * 864e5).toISOString().slice(0, 10);
  return null;
};
const empreinte = (s) => { let h = 2166136261; for (const c of s) h = Math.imul(h ^ c.codePointAt(0), 16777619) >>> 0; return h.toString(16); };
const source = (s) => (/europhyt|traces/.test(norm(s)) ? 'europhyt' : /agrinfo/.test(norm(s)) ? 'agrinfo' : 'manuel');
const produit = (s) => {
  const t = norm(s);
  return !t || /mangu|mango/.test(t) ? 'mangue' : /piment|chil+i|capsicum/.test(t) ? 'piment' : /ananas|pineapple/.test(t) ? 'ananas' : 'autre';
};
const DANGERS = ['pesticides', 'mycotoxines', 'microbiologie', 'organismes nuisibles', 'additifs', 'documentaire'];
const danger = (s, src, titre) => {
  const t = norm(`${s} ${titre}`);
  const connu = DANGERS.find((d) => norm(s).startsWith(d.slice(0, 6)));
  if (connu) return connu;
  if (/mouche|insecte|bactrocera|organisme|fruit fl/.test(t)) return 'organismes nuisibles';
  if (/pesticide|residu|lmr/.test(t)) return 'pesticides';
  if (/aflatox|ochratox|mycotox/.test(t)) return 'mycotoxines';
  if (/salmonel|listeria|coli|bacter/.test(t)) return 'microbiologie';
  return src === 'europhyt' ? 'organismes nuisibles' : 'autre';
};

const lignes = [];
const erreurs = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  if (r.error) { erreurs.push(`Onglet « alertes » illisible : ${JSON.stringify(r.error).slice(0, 200)}`); return; }
  if (!texte(r.titre) && !texte(r.date)) return;
  const d = date(r.date);
  if (!d || !texte(r.titre)) { erreurs.push(`Ligne ${i + 2} : date ou titre manquant`); return; }
  const p = texte(r.pays);
  const code = /^[A-Za-z]{2}$/.test(p) && PAYS[p.toUpperCase()] ? p.toUpperCase() : NOMS[norm(p)] ?? '';
  const src = source(r.source);
  lignes.push({
    source: src,
    reference: empreinte([d, norm(r.titre), norm(p), norm(r.source)].join('|')),
    date_alerte: d,
    produit: produit(r.produit),
    pays: code,
    pays_nom: code ? PAYS[code] : p,
    danger: danger(texte(r.danger), src, texte(r.titre)),
    gravite: '',
    decision: texte(r.decision) || (src === 'europhyt' ? 'interception' : ''),
    titre: texte(r.titre),
    detail: texte(r.detail),
    url: texte(r.lien) || null,
    brut: null,
  });
});
return [{ json: { lignes, recues: lignes.length, erreur: erreurs.join(' ; '), erreurs } }];

// Rassemble les alertes apparues pendant cette exécution (RASFF + Google Sheet). Rien de nouveau : on s'arrête ici.
const MAX_TRADUITES = 40; // les titres RASFF sont en anglais : on traduit les plus récents
const alertes = [
  ...($('Enregistrer RASFF').first().json.nouvelles ?? []),
  ...($json.nouvelles ?? []),
].sort((a, b) => String(b.date_alerte).localeCompare(String(a.date_alerte)));
if (!alertes.length) return [];
const aTraduire = alertes.filter((a) => a.source === 'rasff').slice(0, MAX_TRADUITES);
return [{ json: {
  alertes,
  a_traduire: aTraduire.map((a) => ({ source: a.source, reference: a.reference })),
  liste: aTraduire.map((a, i) => `${i + 1} | ${a.titre}`).join('\n') || 'aucun',
} }];

// Relie chaque ligne « numéro | traduction » de l'IA à son alerte. Ligne manquante ou IA indisponible : titre anglais conservé.
const n = $('Nouvelles alertes').first().json;
const reponse = String($json.text ?? '').replace(/<think>[\s\S]*?<\/think>/g, '');
const titres = [];
for (const ligne of reponse.split('\n')) {
  const m = ligne.match(/^\s*(\d+)\s*[|:.)-]\s*(.+?)\s*$/);
  const cible = m && n.a_traduire[Number(m[1]) - 1];
  if (cible && m[2]) titres.push({ ...cible, titre_fr: m[2].replace(/^["«\s]+|["»\s]+$/g, '') });
}
return [{ json: { titres } }];

parameters.query:
with t as (
  select * from jsonb_to_recordset($1::jsonb) as r(source text, reference text, titre_fr text)
), maj as (
  update ie.alertes_conformite a set titre_fr = t.titre_fr
  from t
  where a.source = t.source and a.reference = t.reference
  returning 1
)
select count(*)::int as titres_traduits from maj;

parameters.jsCode:
// RÉGLAGES : mêmes valeurs que dans le nœud « Préparer les envois » du workflow 02.
const EXPEDITEUR = 'Veille IE <onboarding@resend.dev>';
const ADMIN = 'a-remplacer@exemple.com'; // votre e-mail : reçoit le récapitulatif des nouvelles alertes
const MAX_LIGNES = 30;

const { alertes } = $('Nouvelles alertes').first().json;
const fr = new Map(($('Finaliser les titres').first().json.titres ?? []).map((t) => [`${t.source}|${t.reference}`, t.titre_fr]));
const titre = (a) => fr.get(`${a.source}|${a.reference}`) || a.titre;
const ligne = (a) => `- ${a.date_alerte} · ${a.pays_nom || 'origine non précisée'} · ${a.danger} · ${titre(a)}${a.url ? `\n  ${a.url}` : ''}`;
const suivis = alertes.filter((a) => a.produit !== 'autre');
const autres = alertes.filter((a) => a.produit === 'autre');
const bloc = (liste) => liste.slice(0, MAX_LIGNES).map(ligne).join('\n') + (liste.length > MAX_LIGNES ? `\n… et ${liste.length - MAX_LIGNES} autre(s)` : '');

const parties = [];
if (suivis.length) parties.push(`NOS PRODUITS (mangue, piment, ananas) : ${suivis.length}\n${bloc(suivis)}`);
if (autres.length) parties.push(`AUTRES PRODUITS D'AFRIQUE DE L'OUEST : ${autres.length}\n${bloc(autres)}`);
parties.push("Ces alertes apparaîtront dans le bulletin du vendredi (mangue) et sur le site (feu par pays). Vérifiez-les avant diffusion.");

return [{ json: {
  chemin: 'emails',
  corps: {
    from: EXPEDITEUR,
    to: [ADMIN],
    subject: `[Veille conformité] ${alertes.length} nouvelle(s) alerte(s)` + (suivis.length ? `, dont ${suivis.length} sur nos produits` : ''),
    text: parties.join('\n\n'),
  },
} }];

// Cherche l'identifiant de la mangue dans la liste des produits de la base pesticides de l'UE (code 0163030).
const champ = (x, ...cles) => { for (const k of cles) if (x?.[k] !== undefined && x[k] !== null && x[k] !== '') return x[k]; return null; };
const produits = $input.all().flatMap((i) => (Array.isArray(i.json.value) ? i.json.value : []));
const nom = (p) => String(champ(p, 'product_name', 'productName', 'name') ?? '');
const mangue = produits.find((p) => String(champ(p, 'product_code', 'productCode', 'code') ?? '').replace(/\D/g, '') === '0163030')
  ?? produits.find((p) => /^mangues?\b/i.test(nom(p)))
  ?? produits.find((p) => /mangue|mango/i.test(nom(p)));
if (!mangue) {
  // Identifiant fictif : les nœuds suivants ne trouveront rien et l'erreur sera notée dans ie.journal_collectes.
  return [{ json: { product_id: '0', erreur: `LMR : mangue introuvable parmi ${produits.length} produits. Réponse : ${JSON.stringify($input.first().json).slice(0, 300)}` } }];
}
return [{ json: { product_id: champ(mangue, 'product_id', 'productId', 'id'), nom: nom(mangue) } }];

// Garde, pour chaque substance, la LMR mangue la plus récente (mg/kg). « 0.01* » = limite de quantification : on garde 0.01.
const champ = (x, ...cles) => { for (const k of cles) if (x?.[k] !== undefined && x[k] !== null && x[k] !== '') return x[k]; return null; };
const valeurs = (nom) => { try { return $(nom).all().flatMap((i) => (Array.isArray(i.json.value) ? i.json.value : [])); } catch { return []; } };
const date = (v) => {
  const s = String(v ?? '').trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return null;
};
const nombre = (v) => {
  const s = String(v ?? '').replace(',', '.').replace(/[^0-9.]/g, '');
  return s && Number.isFinite(Number(s)) ? Number(s) : null;
};

const noms = new Map();
for (const s of valeurs('Noms des substances')) {
  const id = champ(s, 'pesticide_residue_id', 'pesticideResidueId', 'substance_id', 'id');
  const n = champ(s, 'pesticide_residue_name', 'pesticideResidueName', 'substance_name', 'name');
  if (id !== null && n) noms.set(String(id), String(n));
}
const mrls = valeurs('LMR mangue (UE)');
const parSubstance = new Map();
for (const m of mrls) {
  const id = champ(m, 'pesticide_residue_id', 'pesticideResidueId', 'substance_id');
  if (id === null) continue;
  const l = {
    residu_id: String(id),
    residu_nom: noms.get(String(id)) ?? String(champ(m, 'pesticide_residue_name', 'pesticideResidueName', 'substance_name') ?? `substance n° ${id}`),
    valeur: nombre(champ(m, 'mrl_value', 'mrlValue', 'mrl')),
    unite: 'mg/kg',
    date_application: date(champ(m, 'entry_into_force_date', 'entryIntoForceDate', 'applicability_date', 'application_date', 'date')),
  };
  const ex = parSubstance.get(l.residu_id);
  if (!ex || (l.date_application && (!ex.date_application || l.date_application > ex.date_application))) parSubstance.set(l.residu_id, l);
}
const lignes = [...parSubstance.values()];
const erreur = lignes.length ? '' : `LMR : aucune valeur lue. ${JSON.stringify($('Trouver la mangue').first().json.erreur ?? $('LMR mangue (UE)').first().json).slice(0, 300)}`;
return [{ json: { lignes, recues: mrls.length, erreur } }];

// RÉGLAGES : mêmes valeurs que dans « Préparer l'e-mail ».
const EXPEDITEUR = 'Veille IE <onboarding@resend.dev>';
const ADMIN = 'a-remplacer@exemple.com';

const { changements = [] } = $json;
if (!changements.length) return [];
return [{ json: {
  chemin: 'emails',
  corps: {
    from: EXPEDITEUR,
    to: [ADMIN],
    subject: `[Veille conformité] ${changements.length} LMR modifiée(s) sur la mangue`,
    text: changements.map((c) => `- ${c.titre}\n  ${c.detail}`).join('\n')
      + "\n\nSource : base pesticides de l'UE. Vérifiez la date d'application avant d'en parler aux abonnés.",
  },
} }];

// Met la veille conformité au format attendu par le site (src/services/marketData.ts).
// RÉGLAGES du feu tricolore : mangue, par pays d'origine, sur les alertes enregistrées (RASFF + saisies du Sheet).
const PAYS_SUIVIS = { CI: "Côte d'Ivoire", SN: 'Sénégal', ML: 'Mali', BF: 'Burkina Faso' };
const ROUGE_A_PARTIR_DE = 3;  // alertes sur les 90 derniers jours
const ORANGE_A_PARTIR_DE = 1; // alertes sur les 12 derniers mois (sinon vert)

const r = $input.first().json;
const parPays = new Map((r.pays ?? []).map((p) => [p.pays, p]));
const feux = [...new Set([...Object.keys(PAYS_SUIVIS), ...parPays.keys()])].map((code) => {
  const p = parPays.get(code) ?? {};
  const n3 = p.n3 ?? 0;
  const n12 = p.n12 ?? 0;
  return {
    pays: code,
    nom: PAYS_SUIVIS[code] ?? p.pays_nom ?? code,
    couleur: n3 >= ROUGE_A_PARTIR_DE ? 'rouge' : n12 >= ORANGE_A_PARTIR_DE ? 'orange' : 'vert',
    alertes3m: n3,
    alertes12m: n12,
    derniere: p.derniere ?? null,
  };
});

const SOURCES = { rasff: 'RASFF (UE)', europhyt: 'EUROPHYT / TRACES', agrinfo: 'AGRINFO', manuel: 'veille IE', 'ue-lmr': 'base pesticides UE' };
const decision = (d) => {
  const t = String(d ?? '').toLowerCase();
  if (/border rejection|refoul/.test(t)) return 'refoulement à la frontière';
  if (/alert/.test(t)) return 'alerte';
  if (/information/.test(t)) return 'information';
  return String(d ?? '');
};
const alertes = (r.alertes ?? []).map((a) => {
  const t = `${a.decision} ${a.gravite}`.toLowerCase();
  const niveau = /border rejection|refoul|^serious|\bserious/.test(t) && !/not serious/.test(t) ? 'urgent'
    : /information|not serious/.test(t) ? 'info' : 'attention';
  return {
    id: `${a.source}-${a.reference}`,
    titre: a.titre,
    produit: a.produit,
    niveau,
    date: a.date_alerte,
    resume: [a.danger !== 'autre' ? a.danger : '', a.pays_nom ? `origine ${a.pays_nom}` : '', decision(a.decision), SOURCES[a.source] ?? a.source]
      .filter(Boolean).join(' · '),
